import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Class: ItemValue","description":"","frontmatter":{},"headers":[],"relativePath":"api/helix/classes/ItemValue.md","filePath":"api/helix/classes/ItemValue.md"}'),n={name:"api/helix/classes/ItemValue.md"};function c(d,e,i,s,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../">helix</a> / ItemValue</p><h1 id="class-itemvalue" tabindex="-1">Class: ItemValue <a class="header-anchor" href="#class-itemvalue" aria-label="Permalink to &quot;Class: ItemValue&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L156" target="_blank" rel="noreferrer">core/values/item.ts:156</a></p><p>An item - id plus an optional, structured definition of its data (name, model data, enchantments, lore, raw components). <strong>The single source of truth for an item across the pack:</strong> pass the same object to <code>give</code> to grant it, or to <code>Predicate.matchTool(...)</code> / <code>Selector.holding(...)</code> to check for it. It lowers itself per target version (data components on 1.20.5+, NBT before) and per context (item-stack string vs <code>item_predicate</code> JSON) - you never re-encode it.</p><p>const excalibur = Item(&quot;diamond_sword&quot;) .named(&quot;Excalibur&quot;).enchant(&quot;sharpness&quot;, 5).modelData(1234);</p><p>ctx.playerGive(Selector.nearest(), excalibur); // give …[components] 1 ctx.if(predicateCheck(dp.predicate(&quot;excalibur&quot;, // if predicate … run … Predicate.matchTool(excalibur))), …);</p><p>Bare ids and <code>#tags</code> still work (<code>Item(&quot;diamond&quot;)</code>, <code>Item(&quot;#planks&quot;)</code>), and <code>.data(raw)</code> is a verbatim escape hatch for hand-written component/NBT strings.</p><h2 id="implements" tabindex="-1">Implements <a class="header-anchor" href="#implements" aria-label="Permalink to &quot;Implements&quot;">​</a></h2><ul><li><a href="./../interfaces/CommandValue.html"><code>CommandValue</code></a></li></ul><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h3><blockquote><p><strong>new ItemValue</strong>(<code>id</code>): <code>ItemValue</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L168" target="_blank" rel="noreferrer">core/values/item.ts:168</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="id" tabindex="-1">id <a class="header-anchor" href="#id" aria-label="Permalink to &quot;id&quot;">​</a></h5><p><code>string</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>ItemValue</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="baseid" tabindex="-1">baseId() <a class="header-anchor" href="#baseid" aria-label="Permalink to &quot;baseId()&quot;">​</a></h3><blockquote><p><strong>baseId</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L280" target="_blank" rel="noreferrer">core/values/item.ts:280</a></p><p>The normalized item id with no data/components (<code>minecraft:diamond</code>, <code>#minecraft:planks</code>).</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p><hr><h3 id="canplaceon" tabindex="-1">canPlaceOn() <a class="header-anchor" href="#canplaceon" aria-label="Permalink to &quot;canPlaceOn()&quot;">​</a></h3><blockquote><p><strong>canPlaceOn</strong>(...<code>blocks</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L234" target="_blank" rel="noreferrer">core/values/item.ts:234</a></p><p>Restrict where this item may be placed in adventure mode (<code>can_place_on</code>). Each argument is a block id or <code>#tag</code> (<code>&quot;minecraft:stone&quot;</code>, <code>&quot;#minecraft:stone_bricks&quot;</code>).</p><p>The shape is an <code>AdventureModePredicate</code>, which does <em>not</em> survive a naive hand-encoding: on 1.20.5+ it lowers to the structured <code>can_place_on</code> component (a <code>{blocks:…}</code> block predicate - the codec is <code>compactListCodec(BlockPredicate)</code>, so there is no <code>predicates:</code> wrapper), while before components it is the flat NBT <code>CanPlaceOn:[…]</code> string list - the same reason the pack never hand-writes item NBT. Whether the restriction shows in the tooltip is a separate concern (<code>tooltip_display</code> on modern, <code>HideFlags</code> before).</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="blocks" tabindex="-1">blocks <a class="header-anchor" href="#blocks" aria-label="Permalink to &quot;blocks&quot;">​</a></h5><p>...<code>string</code>[]</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="component" tabindex="-1">component() <a class="header-anchor" href="#component" aria-label="Permalink to &quot;component()&quot;">​</a></h3><blockquote><p><strong>component</strong>(<code>name</code>, <code>stackValue</code>, <code>predicate?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L270" target="_blank" rel="noreferrer">core/values/item.ts:270</a></p><p>A raw data component for things the typed builders don&#39;t model yet, e.g. <code>.component(&quot;unbreakable&quot;, &quot;{}&quot;)</code>. <code>key</code>/<code>json</code> are optional predicate counterparts so it can still participate in <code>match_tool</code> matching.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h5><p><code>string</code></p><h5 id="stackvalue" tabindex="-1">stackValue <a class="header-anchor" href="#stackvalue" aria-label="Permalink to &quot;stackValue&quot;">​</a></h5><p><code>string</code></p><h5 id="predicate" tabindex="-1">predicate? <a class="header-anchor" href="#predicate" aria-label="Permalink to &quot;predicate?&quot;">​</a></h5><h6 id="json" tabindex="-1">json <a class="header-anchor" href="#json" aria-label="Permalink to &quot;json&quot;">​</a></h6><p><code>unknown</code></p><h6 id="key" tabindex="-1">key <a class="header-anchor" href="#key" aria-label="Permalink to &quot;key&quot;">​</a></h6><p><code>string</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="componentsjson" tabindex="-1">componentsJson() <a class="header-anchor" href="#componentsjson" aria-label="Permalink to &quot;componentsJson()&quot;">​</a></h3><blockquote><p><strong>componentsJson</strong>(<code>version</code>): <code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L474" target="_blank" rel="noreferrer">core/values/item.ts:474</a></p><p>The item&#39;s data components as a <code>{ &quot;minecraft:custom_name&quot;: ... }</code> map, for a loot/recipe <code>set_components</code> function or any data-file that carries components inline. Built from the same definitions as <a href="#render">render</a>/<a href="#topredicate">toPredicate</a>, so a loot-granted item matches its give&#39;d / predicate forms. Empty on versions before components, or for an item defined only via raw <code>.data(...)</code> (which can&#39;t be parsed back into structured components).</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="version" tabindex="-1">version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;version&quot;">​</a></h5><p><a href="./../interfaces/VersionProfile.html"><code>VersionProfile</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;</p><hr><h3 id="count" tabindex="-1">count() <a class="header-anchor" href="#count" aria-label="Permalink to &quot;count()&quot;">​</a></h3><blockquote><p><strong>count</strong>(<code>n</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L177" target="_blank" rel="noreferrer">core/values/item.ts:177</a></p><p>Stack size carried with the item (used by <code>give</code>; a count range for predicates).</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="n" tabindex="-1">n <a class="header-anchor" href="#n" aria-label="Permalink to &quot;n&quot;">​</a></h5><p><code>number</code></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="data" tabindex="-1">data() <a class="header-anchor" href="#data" aria-label="Permalink to &quot;data()&quot;">​</a></h3><blockquote><p><strong>data</strong>(<code>data</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L171" target="_blank" rel="noreferrer">core/values/item.ts:171</a></p><p>Verbatim data escape hatch (<code>[components]</code> on 1.20.5+, <code>{nbt}</code> before).</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="data-1" tabindex="-1">data <a class="header-anchor" href="#data-1" aria-label="Permalink to &quot;data&quot;">​</a></h5><p><code>string</code></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="enchant" tabindex="-1">enchant() <a class="header-anchor" href="#enchant" aria-label="Permalink to &quot;enchant()&quot;">​</a></h3><blockquote><p><strong>enchant</strong>(<code>enchantment</code>, <code>level</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L211" target="_blank" rel="noreferrer">core/values/item.ts:211</a></p><p>Add an enchantment + level (repeatable).</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="enchantment" tabindex="-1">enchantment <a class="header-anchor" href="#enchantment" aria-label="Permalink to &quot;enchantment&quot;">​</a></h5><p><code>string</code> | <a href="./../interfaces/CommandValue.html"><code>CommandValue</code></a></p><h5 id="level" tabindex="-1">level <a class="header-anchor" href="#level" aria-label="Permalink to &quot;level&quot;">​</a></h5><p><code>number</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="getcount" tabindex="-1">getCount() <a class="header-anchor" href="#getcount" aria-label="Permalink to &quot;getCount()&quot;">​</a></h3><blockquote><p><strong>getCount</strong>(): <code>number</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L287" target="_blank" rel="noreferrer">core/values/item.ts:287</a></p><p>The count set via <a href="#count">count</a>, if any.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>number</code> | <code>undefined</code></p><hr><h3 id="lore" tabindex="-1">lore() <a class="header-anchor" href="#lore" aria-label="Permalink to &quot;lore()&quot;">​</a></h3><blockquote><p><strong>lore</strong>(...<code>lines</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L217" target="_blank" rel="noreferrer">core/values/item.ts:217</a></p><p>Append lore lines (<code>lore</code> / <code>display.Lore</code>). Each line is a string or styled <a href="./../type-aliases/TextComponent.html">TextComponent</a>.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="lines" tabindex="-1">lines <a class="header-anchor" href="#lines" aria-label="Permalink to &quot;lines&quot;">​</a></h5><p>...<a href="./../type-aliases/TextComponent.html"><code>TextComponent</code></a>[]</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="model" tabindex="-1">model() <a class="header-anchor" href="#model" aria-label="Permalink to &quot;model()&quot;">​</a></h3><blockquote><p><strong>model</strong>(<code>handle</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L205" target="_blank" rel="noreferrer">core/values/item.ts:205</a></p><p>Point this item at a resource-pack model via its <a href="./ModelRef.html">ModelRef</a> (from <code>dp.model(...)</code>) or a bare <code>&lt;ns&gt;:name</code>. Lowers to the <code>item_model</code> component on 1.21.4+; on older versions it needs the ref&#39;s legacy <code>custom_model_data</code> number (see <a href="./ModelRef.html">ModelRef</a>), else rendering throws.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="handle" tabindex="-1">handle <a class="header-anchor" href="#handle" aria-label="Permalink to &quot;handle&quot;">​</a></h5><p><code>string</code> | <a href="./ModelRef.html"><code>ModelRef</code></a></p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="modeldata" tabindex="-1">modelData() <a class="header-anchor" href="#modeldata" aria-label="Permalink to &quot;modelData()&quot;">​</a></h3><blockquote><p><strong>modelData</strong>(<code>n</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L194" target="_blank" rel="noreferrer">core/values/item.ts:194</a></p><p>Raw <code>custom_model_data</code> / <code>CustomModelData</code> integer - the escape hatch for a model you manage in an external resource pack. Prefer <a href="#model">model</a> with a <a href="./ModelRef.html">ModelRef</a> from <code>dp.model(...)</code>, which generates the model + emits the typed <code>item_model</code> component instead of a magic number.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="n-1" tabindex="-1">n <a class="header-anchor" href="#n-1" aria-label="Permalink to &quot;n&quot;">​</a></h5><p><code>number</code></p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="named" tabindex="-1">named() <a class="header-anchor" href="#named" aria-label="Permalink to &quot;named()&quot;">​</a></h3><blockquote><p><strong>named</strong>(<code>name</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L183" target="_blank" rel="noreferrer">core/values/item.ts:183</a></p><p><code>custom_name</code> / <code>display.Name</code>. Accepts a plain string or a styled <a href="./../type-aliases/TextComponent.html">TextComponent</a>.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="name-1" tabindex="-1">name <a class="header-anchor" href="#name-1" aria-label="Permalink to &quot;name&quot;">​</a></h5><p><a href="./../type-aliases/TextComponent.html"><code>TextComponent</code></a></p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="render" tabindex="-1">render() <a class="header-anchor" href="#render" aria-label="Permalink to &quot;render()&quot;">​</a></h3><blockquote><p><strong>render</strong>(<code>version</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L437" target="_blank" rel="noreferrer">core/values/item.ts:437</a></p><p>The full item-stack string (<code>id</code> + data), version-aware.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="version-1" tabindex="-1">version <a class="header-anchor" href="#version-1" aria-label="Permalink to &quot;version&quot;">​</a></h5><p><a href="./../interfaces/VersionProfile.html"><code>VersionProfile</code></a></p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p><h4 id="implementation-of" tabindex="-1">Implementation of <a class="header-anchor" href="#implementation-of" aria-label="Permalink to &quot;Implementation of&quot;">​</a></h4><p><a href="./../interfaces/CommandValue.html"><code>CommandValue</code></a>.<a href="./../interfaces/CommandValue.html#render"><code>render</code></a></p><hr><h3 id="renderdata" tabindex="-1">renderData() <a class="header-anchor" href="#renderdata" aria-label="Permalink to &quot;renderData()&quot;">​</a></h3><blockquote><p><strong>renderData</strong>(<code>version</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L424" target="_blank" rel="noreferrer">core/values/item.ts:424</a></p><p>Just the data fragment appended to the id in stack form (<code>[...]</code>/<code>{...}</code>/<code>&quot;&quot;</code>).</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="version-2" tabindex="-1">version <a class="header-anchor" href="#version-2" aria-label="Permalink to &quot;version&quot;">​</a></h5><p><a href="./../interfaces/VersionProfile.html"><code>VersionProfile</code></a></p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p><hr><h3 id="stacknbt" tabindex="-1">stackNbt() <a class="header-anchor" href="#stacknbt" aria-label="Permalink to &quot;stackNbt()&quot;">​</a></h3><blockquote><p><strong>stackNbt</strong>(): <a href="./../interfaces/CommandValue.html"><code>CommandValue</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L532" target="_blank" rel="noreferrer">core/values/item.ts:532</a></p><p><a href="#tostacknbt">toStackNbt</a> deferred, so the stack can be dropped straight into an <code>Nbt({ Item: … })</code> compound and rendered with everything around it.</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/CommandValue.html"><code>CommandValue</code></a></p><hr><h3 id="topredicate" tabindex="-1">toPredicate() <a class="header-anchor" href="#topredicate" aria-label="Permalink to &quot;toPredicate()&quot;">​</a></h3><blockquote><p><strong>toPredicate</strong>(<code>version</code>): <code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L448" target="_blank" rel="noreferrer">core/values/item.ts:448</a></p><p>This item as an <code>item_predicate</code> JSON object (the body of a <code>match_tool</code> condition, or a recipe/equipment item check). Built from the same component definitions as <a href="#render">render</a>, so a give&#39;d item matches its own predicate. Raw <code>.data(...)</code> strings can&#39;t be parsed back, so an item defined only that way matches by id alone.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="version-3" tabindex="-1">version <a class="header-anchor" href="#version-3" aria-label="Permalink to &quot;version&quot;">​</a></h5><p><a href="./../interfaces/VersionProfile.html"><code>VersionProfile</code></a></p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;</p><hr><h3 id="tostacknbt" tabindex="-1">toStackNbt() <a class="header-anchor" href="#tostacknbt" aria-label="Permalink to &quot;toStackNbt()&quot;">​</a></h3><blockquote><p><strong>toStackNbt</strong>(<code>version</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L500" target="_blank" rel="noreferrer">core/values/item.ts:500</a></p><p>This item as an <strong>item-stack NBT compound</strong> - the shape an entity or block entity stores a stack in (an item frame&#39;s <code>Item</code>, a container&#39;s <code>Items</code> entry, a dropped item&#39;s <code>Item</code>), as opposed to the command-line stack string <a href="#render">render</a> produces or the predicate JSON <a href="#topredicate">toPredicate</a> produces.</p><p>Same definitions, third rendering, so a named item summoned inside a frame is the same value that <code>give</code>s and that a <code>match_tool</code> predicate matches. Version aware in two places at once: <code>count</code>/<code>components</code> on 1.20.5+, <code>Count:1b</code>/<code>tag</code> before it.</p><p>A raw <code>.data(...)</code> escape hatch can&#39;t be lowered into this form (the string is stack syntax, not NBT), so an item defined that way throws rather than silently emitting a stack missing its data.</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="version-4" tabindex="-1">version <a class="header-anchor" href="#version-4" aria-label="Permalink to &quot;version&quot;">​</a></h5><p><a href="./../interfaces/VersionProfile.html"><code>VersionProfile</code></a></p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p><hr><h3 id="writtenbook" tabindex="-1">writtenBook() <a class="header-anchor" href="#writtenbook" aria-label="Permalink to &quot;writtenBook()&quot;">​</a></h3><blockquote><p><strong>writtenBook</strong>(<code>title</code>, <code>author</code>, <code>pages</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/c1ecec800a3d331b1d0f004927f506f5ad6a226c/helix/src/core/values/item.ts#L260" target="_blank" rel="noreferrer">core/values/item.ts:260</a></p><p><code>minecraft:written_book_content</code> - a resolved written book&#39;s title, author and pages. Each page is a plain string, a single styled <code>text(...)</code> span, or an array of spans sharing one line (see <a href="./../functions/pageLines.html">pageLines</a>/<a href="./../functions/rightAlign.html">rightAlign</a> for building those) - the array form lowers to one base component carrying those spans as <code>extra</code> siblings.</p><p>Each page is <code>Filterable&lt;Component&gt;</code> per the component&#39;s own codec - a real text component stored as NBT structure, <em>not</em> a JSON string - so this renders each page through the shared <a href="./../functions/toSnbt.html">toSnbt</a> serializer directly, the same as any other structured component value. (Earlier revisions of this builder JSON-stringified each page into a quoted SNBT string, matching <code>writable_book_content</code>&#39;s plain-string pages rather than this component&#39;s actual schema; that produced a book whose pages displayed their own JSON source as literal text - pageJson is typed <code>Record&lt;string, NbtInput&gt;</code>, not <code>NbtInput</code>, specifically so a page can&#39;t be a bare string and that mistake can&#39;t compile again.)</p><p>Components only - a target predating 1.20.5 throws rather than silently dropping the book&#39;s content.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="title" tabindex="-1">title <a class="header-anchor" href="#title" aria-label="Permalink to &quot;title&quot;">​</a></h5><p><code>string</code></p><h5 id="author" tabindex="-1">author <a class="header-anchor" href="#author" aria-label="Permalink to &quot;author&quot;">​</a></h5><p><code>string</code></p><h5 id="pages" tabindex="-1">pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;pages&quot;">​</a></h5><p>(<code>string</code> | <a href="./TellrawPart.html"><code>TellrawPart</code></a> | <a href="./TellrawPart.html"><code>TellrawPart</code></a>[])[]</p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p>',209)])])}const p=a(n,[["render",c]]);export{u as __pageData,p as default};
